jv jq_parse_json_arg(jq_state *jq, const char *text) {
  if (jq->progname == NULL) jq->progname = "jq";
  jv v = jv_parse(text);
  if (!jv_is_valid(v)) {
    jv msg = jv_invalid_get_msg(v);
    fprintf(stderr, "%s: Invalid JSON text passed to --jsonargs\n%s\n",
            jq_get_progname(jq), jv_string_value(msg));
